/**
 * generated by stackra gen from src/routes/product.route.ts, src/routes/site.layout.ts,
 * src/config/seo.config.ts (the SEO defaults), src/config/edge.config.ts (cache:
 * CacheProfile.Catalogue) and src/config/i18n.config.ts — do not edit
 * Purpose: the React Router framework-mode module for one `@Route` class: turns the class's loader
 *          and meta and its `component` option into the exports the router expects, building the
 *          RouteContext (`site` from the layout's resolve, `query`/`action` over the load context's
 *          public clients for the site's locale and market, `config`, `env`, the request's `t`,
 *          `params`, `search`, `path`, `href`) and mapping `cache` to the `Cache-Control` header of
 *          the edge profile. One such file exists per route class; this is the sample for
 *          `/store/:slug`.
 * Boundary: delegation only; the class owns every behaviour. The module imports no server-only
 *           code: the clients and the env arrive in the load context the Worker builds, so React
 *           Router's client build keeps only `default` and `meta`.
 * Runtime: isomorphic
 */
import { routeAdapter } from "@stackra/navigation/router";
import type { Route } from "./+types/product";
import { ProductRoute } from "#src/routes/product.route";
import { SiteLayout } from "#src/routes/site.layout";
import { translatorFor } from "#stackra/i18n";

/**
 * The adapter binds the class once; every export below delegates to it. It reads the decorator
 * options (`component`, `layout`, `cache`) on the first request, never at import.
 */
const adapter = routeAdapter(ProductRoute, { layout: SiteLayout, t: translatorFor });

/**
 * Resolves the layout's `site` (cached per request), builds the context from the load context,
 * runs `ProductRoute.loader`.
 */
export async function loader(args: Route.LoaderArgs) {
  return adapter.loader(args);
}

/**
 * The SEO default chain, in order: seo.config.ts defaults (title template, site name, OG card) →
 * the route's static options (`title`) → `ProductRoute.meta(ctx)` → the tenant's SEO record. The
 * adapter derives canonical, hreflang alternates and `noindex` for a non-indexable site, and
 * escapes every JSON-LD block.
 */
export const meta: Route.MetaFunction = (args) => adapter.meta(args);

/** `CacheProfile.Catalogue` → the profile's `Cache-Control` from `ctx.config(EdgeConfig)`. */
export const headers: Route.HeadersFunction = (args) => adapter.headers(args);

/** The class's `component` option with `{ data, params, search }` from this module's loader. */
export default function ProductRouteModule({ loaderData, params }: Route.ComponentProps) {
  return adapter.render({ loaderData, params });
}
